import{_ as l,a0 as o,w as p,s as r,ao as d,I as n,a1 as i,A as a,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Linux 下鎖住鍵盤和鼠標而不鎖屏 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 下鎖住鍵盤和鼠標而不鎖屏 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 下鎖住鍵盤和鼠標而不鎖屏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 下鎖住鍵盤和鼠標而不鎖屏 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180817 How To Lock The Keyboard And Mouse, But Not The Screen In Linux","title":"如何在 Linux 下鎖住鍵盤和鼠標而不鎖屏","tag":"201810","desc":""},"relativePath":"201810/20180817 How To Lock The Keyboard And Mouse, But Not The Screen In Linux.md","filePath":"[post].md"}'),h={name:"201810/20180817 How To Lock The Keyboard And Mouse, But Not The Screen In Linux.md"};function c(g,s,u,k,b,x){const e=o("Link");return p(),r("div",null,[s[16]||(s[16]=d(`<h1 id="如何在-linux-下鎖住鍵盤和鼠標而不鎖屏" tabindex="-1">如何在 Linux 下鎖住鍵盤和鼠標而不鎖屏 <a class="header-anchor" href="#如何在-linux-下鎖住鍵盤和鼠標而不鎖屏" aria-label="Permalink to “如何在 Linux 下鎖住鍵盤和鼠標而不鎖屏”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/09/Lock-The-Keyboard-And-Mouse-720x340.jpg" alt=""></p><p>我四歲的侄女是個好奇的孩子，她非常喜愛“阿凡達”電影，當阿凡達電影在播放時，她是如此的專注，好似眼睛粘在了屏幕上。但問題是當她觀看電影時，她經常會碰到鍵盤上的某個鍵或者移動了鼠標，又或者是點擊了鼠標的按鈕。有時她非常意外地按了鍵盤上的某個鍵，從而將電影關閉或者暫停了。所以我就想找個方法來將鍵盤和鼠標都鎖住，但屏幕不會被鎖住。幸運的是，我在 Ubuntu 論壇上找到了一個完美的解決方法。假如在你正看着屏幕上的某些重要的事情時，你不想讓你的小貓或者小狗在你的鍵盤上行走，或者讓你的孩子在鍵盤上瞎搞一氣，那我建議你試試 <strong>xtrlock</strong> 這個工具。它很簡單但非常實用，你可以鎖定屏幕的顯示直到用户在鍵盤上輸入自己設定的密碼（LCTT 譯註：就是用户自己的密碼，例如用來打開屏保的那個密碼，不需要單獨設定）。在這篇簡單的教程中，我將為你展示如何在 Linux 下鎖住鍵盤和鼠標，而不鎖掉屏幕。這個技巧幾乎可以在所有的 Linux 操作系統中生效。</p><h3 id="安裝-xtrlock" tabindex="-1">安裝 xtrlock <a class="header-anchor" href="#安裝-xtrlock" aria-label="Permalink to “安裝 xtrlock”">​</a></h3><p>xtrlock 軟件包在大多數 Linux 操作系統的默認軟件倉庫中都可以獲取到。所以你可以使用你安裝的發行版的包管理器來安裝它。</p><p>在 <strong>Arch Linux</strong> 及其衍生發行版中，運行下面的命令來安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S xtrlock</span></span></code></pre></div><p>在 <strong>Fedora</strong> 上使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install xtrlock</span></span></code></pre></div><p>在 <strong>RHEL、CentOS</strong> 上使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install xtrlock</span></span></code></pre></div><p>在 <strong>SUSE/openSUSE</strong> 上使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper install xtrlock</span></span></code></pre></div><p>在 <strong>Debian、Ubuntu、Linux Mint</strong> 上使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install xtrlock</span></span></code></pre></div><h3 id="使用-xtrlock-鎖住鍵盤和鼠標但不鎖屏" tabindex="-1">使用 xtrlock 鎖住鍵盤和鼠標但不鎖屏 <a class="header-anchor" href="#使用-xtrlock-鎖住鍵盤和鼠標但不鎖屏" aria-label="Permalink to “使用 xtrlock 鎖住鍵盤和鼠標但不鎖屏”">​</a></h3><p>安裝好 xtrlock 後，你需要根據你的選擇來創建一個快捷鍵，通過這個快捷鍵來鎖住鍵盤和鼠標。</p><p>（LCTT 譯註：譯者在自己的系統（Arch + Deepin）中發現這裏的到下面創建快捷鍵的部分可以不必做，依然生效。）</p><p>在 <code>/usr/local/bin</code> 目錄下創建一個名為 <code>lockkbmouse</code> 的新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /usr/local/bin/lockkbmouse</span></span></code></pre></div><p>然後將下面的命令添加到這個文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>sleep 1 &amp;&amp; xtrlock</span></span></code></pre></div><p>保存並關閉這個文件。</p><p>然後使用下面的命令來使得它可以被執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod a+x /usr/local/bin/lockkbmouse</span></span></code></pre></div><p>接着，我們就需要創建快捷鍵了。</p><h4 id="創建快捷鍵" tabindex="-1">創建快捷鍵 <a class="header-anchor" href="#創建快捷鍵" aria-label="Permalink to “創建快捷鍵”">​</a></h4><p><strong>在 Arch Linux MATE 桌面中</strong></p><p>依次點擊 “System -&gt; Preferences -&gt; Hardware -&gt; keyboard Shortcuts”</p><p>然後點擊 “Add” 來創建快捷鍵。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/09/Keyboard-Shortcuts_001.png" alt=""></p><p>首先鍵入你的這個快捷鍵的名稱，然後將下面的命令填入命令框中，最後點擊 “Apply” 按鈕。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash -c &quot;sleep 1 &amp;&amp; xtrlock&quot;</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/09/Keyboard-Shortcuts_002.png" alt=""></p><p>為了能夠給這個快捷鍵賦予快捷方式，需要選中它或者雙擊它然後輸入你選定的快捷鍵組合，例如我使用 <code>Alt+k</code> 這組快捷鍵。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/09/Keyboard-Shortcuts_003.png" alt=""></p><p>如果要清除這個快捷鍵組合，按住 <code>BACKSPACE</code> 鍵就可以了。完成後，關閉鍵盤設定窗口。</p><p><strong>在 Ubuntu GNOME 桌面中</strong></p><p>依次進入 “System Settings -&gt; Devices -&gt; Keyboard”，然後點擊 “+” 這個符號。</p><p>鍵入你快捷鍵的名稱並將下面的命令加到命令框裏面，然後點擊 “Add” 按鈕。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash -c &quot;sleep 1 &amp;&amp; xtrlock&quot;</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/Add-xtrlock-shortcut.png" alt=""></p><p>接下來為這個新建的快捷鍵賦予快捷方式。我們只需要選擇或者雙擊 “Set shortcut” 這個按鈕就可以了。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/set-shortcut-key-1.png" alt=""></p><p>然後你將看到下面的一屏。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/set-shortcut-key-2.png" alt=""></p><p>輸入你選定的快捷鍵組合，例如我使用 <code>Alt+k</code>。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/set-shortcut-key-3.png" alt=""></p><p>如果要清除這個快捷鍵組合，則可以按 <code>BACKSPACE</code> 這個鍵。這樣快捷鍵便設定好了，完成這個後，關閉鍵盤設定窗口。</p><p>從現在起，每當你輸入剛才設定的快捷鍵（在我們的示例中是 <code>ATL+K</code>），鼠標的指針便會變成一個掛鎖的模樣。現在，鍵盤和鼠標便被鎖定了，這時你便可以自在地觀看你的電影或者做其他你想做的事兒。即便是你的孩子或者寵物碰了鍵盤上的某些鍵或者點擊了鼠標，這些操作都不會起作用。</p><p>因為 <code>xtrlock</code> 已經在工作了。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/xtrclock-1.png" alt=""></p><p>你看到了那個小的鎖按鈕了嗎？它意味着鍵盤和鼠標已經被鎖定了。即便你移動這個鎖按鈕，也不會發生任何事情。後台的任務在一直執行，直到你將屏幕解除，然後手動停掉運行中的任務。</p><h3 id="將鍵盤和鼠標解鎖" tabindex="-1">將鍵盤和鼠標解鎖 <a class="header-anchor" href="#將鍵盤和鼠標解鎖" aria-label="Permalink to “將鍵盤和鼠標解鎖”">​</a></h3><p>要將鍵盤和鼠標解鎖，只需要輸入你的密碼然後敲擊回車鍵就可以了，在輸入的過程中你將看不到密碼。只需要輸入然後敲回車鍵就可以了。在你輸入了正確的密碼後，鼠標和鍵盤就可以再工作了。假如你輸入了一個錯誤的密碼，你將聽到警告聲。按 <code>ESC</code> 來清除輸入的錯誤密碼，然後重新輸入正確的密碼。要去掉未完全輸入完的密碼中的一個字符，只需要按 <code>BACKSPACE</code> 或者 <code>DELETE</code> 鍵就可以了。</p><h3 id="要是我被永久地鎖住了怎麼辦" tabindex="-1">要是我被永久地鎖住了怎麼辦？ <a class="header-anchor" href="#要是我被永久地鎖住了怎麼辦" aria-label="Permalink to “要是我被永久地鎖住了怎麼辦？”">​</a></h3><p>以防你被永久地鎖定了屏幕，切換至一個 TTY（例如 <code>CTRL+ALT+F2</code>）然後運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo killall xtrlock</span></span></code></pre></div><p>或者你還可以使用 <code>chvt</code> 命令來在 TTY 和 X 會話之間切換。</p><p>例如，如果要切換到 TTY1，則運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chvt 1</span></span></code></pre></div><p>要切換回 X 會話，則鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chvt 7</span></span></code></pre></div><p>不同的發行版使用了不同的快捷鍵組合來在不同的 TTY 間切換。請參考你安裝的對應發行版的官方網站了解更多詳情。</p><p>如果想知道更多 xtrlock 的信息，請參考 man 頁：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man xtrlock</span></span></code></pre></div><p>那麼這就是全部了。希望這個指南可以幫到你。假如你發現這個指南很有用，請花點時間將這個指南共享到你的朋友圈並支持我們（OSTechNix）。</p><p><strong>資源：</strong></p>`,68)),n("ul",null,[n("li",null,[i(e,{href:"https://ubuntuforums.org/showthread.php?t=993800"},{default:a(()=>[...s[0]||(s[0]=[n("strong",null,"Ubuntu 論壇",-1)])]),_:1})])]),s[17]||(s[17]=n("hr",null,null,-1)),n("p",null,[s[2]||(s[2]=t("via: ",-1)),i(e,{href:"https://www.ostechnix.com/lock-keyboard-mouse-not-screen-linux/"},{default:a(()=>[...s[1]||(s[1]=[t("https://www.ostechnix.com/lock-keyboard-mouse-not-screen-linux/",-1)])]),_:1})]),n("p",null,[s[7]||(s[7]=t("作者：",-1)),i(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[3]||(s[3]=[t("SK",-1)])]),_:1}),s[8]||(s[8]=t(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[4]||(s[4]=[t("lujun9972",-1)])]),_:1}),s[9]||(s[9]=t(" 譯者：",-1)),i(e,{href:"https://github.com/FSSlc"},{default:a(()=>[...s[5]||(s[5]=[t("FSSlc",-1)])]),_:1}),s[10]||(s[10]=t(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[6]||(s[6]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[11]||(s[11]=[t("LCTT",-1)])]),_:1}),s[14]||(s[14]=t(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...s[12]||(s[12]=[t("Linux中國",-1)])]),_:1}),s[15]||(s[15]=t(" 榮譽推出",-1))])])}const w=l(h,[["render",c]]);export{y as __pageData,w as default};
